    public BigDecimal refundOnCancellation(Price price) {
        return price.total();
    }

    public BigDecimal getDiscount(String companyCode) {
        return CORPORATE_DISCOUNTS.getOrDefault(companyCode, BigDecimal.ZERO);
    }
}

